/* Put the beach and winter mechanisms back into the painted world. */
'use strict';
const paintedStageWorld=stageWorld;
const AdventureLocations={seaside:{dials:[[34,24],[58,36],[87,23]],symbols:[[45,76],[75,58],[84,14]],extra:[['bottle','漂流瓶','🍾',31,65],['tide','潮汐池','🌀',80,76],['friend','海鸥阿白','🕊',10,83]]},winter:{dials:[[18,65],[44,24],[78,50]],symbols:[[38,56],[65,40],[83,76]],extra:[['train','小火车道岔','🚂',89,17],['snowman','雪人的衣帽架','⛄',10,37],['friend','雪夜小邮差','🦉',36,84]]}};
function sceneExtras(id){state.sceneExtras??={};return state.sceneExtras[id]??={bottle:0,tide:0,train:[0,0,0],hat:0,scarf:0,notes:[]};}
function sceneMemento(id,key){const e=sceneExtras(id);if(!e.notes.includes(key))e.notes.push(key);save();}
function futureDevice(stage,s,name,icon,x,y){const status=s.stage<stage?'暂未开始':s.stage===stage?'进行中':'已完成';return `<button class="away-spot scenery-device ${s.stage<stage?'dormant-device':''}" data-future-device="${stage}" style="left:${x}%;top:${y}%" title="${name} · ${status}" aria-label="${name}，${status}"><i>${icon}</i><span>${name}${s.stage>stage?' ✓':''}</span></button>`;}
stageWorld=function(scene,s){const loc=AdventureLocations[scene.id],winter=scene.id==='winter',extras=loc.extra.map(([id,name,icon,x,y])=>`<button class="away-spot side-discovery" data-scene-extra="${id}" style="left:${x}%;top:${y}%" title="${name} · 点开探索"><i>${icon}</i><span>${name}</span></button>`).join('');
 let main=s.stage===0?paintedStageWorld(scene,s):scene.targets.map(t=>futureDevice(0,s,t.name,t.icon,t.x,t.y)).join('');
 if(s.stage===1){if(!winter){main+=loc.dials.map(([x,y],i)=>`<button class="away-spot painted-dial" data-away-dial="${i}" style="left:${x}%;top:${y}%" aria-label="转动第${i+1}面航标"><i class="beacon-arrow">${['↑','→','↓','←'][s.dials[i]]}</i><span>航标 ${i+1} · ${['北','东','南','西'][s.dials[i]]}</span></button>`).join('')+`<div class="away-signpost" style="left:42%;top:70%"><span>码头木牌刻着</span><strong>东 → 南 → 西</strong><p>走到三面航标旁，点击调整方向。</p><button id="awayCheck" class="primary">试亮航灯</button></div>`;}else{main+=`<svg class="winter-wiring" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><path d="M18 72Q28 48 44 30M44 31Q60 54 78 56M78 57Q45 85 18 72"/></svg>`+loc.dials.map(([x,y],i)=>`<div class="painted-lamp ${s.lights[i]?'lit':''}" style="left:${x}%;top:${y}%"><span>${s.lights[i]?'💡':'◯'}</span><small>街灯 ${i+1}</small></div><button class="away-spot painted-switch" data-away-switch-light="${i}" style="left:${x}%;top:${y+12}%"><i>⏻</i><span>开关 ${i+1} · ${['连接灯1、2','连接灯2、3','连接全部灯'][i]}</span></button>`).join('')+`<div class="away-signpost winter-signpost" style="left:40%;top:59%"><span>把街灯都点亮</span><p>每个开关会翻转连着的灯，沿电线找找它们的关系。</p><button id="awayCheck" class="primary">确认整街亮灯</button></div>`;}}
 else main+=loc.dials.map(([x,y],i)=>futureDevice(1,s,winter?'街灯开关 '+(i+1):'归航灯 '+(i+1),winter?'💡':'⌖',x,y)).join('');
 if(s.stage===2){main+=scene.symbols.map(([key,icon,label],i)=>{const[x,y]=loc.symbols[i];return `<button class="away-spot melody-find" data-away-symbol="${key}" style="left:${x}%;top:${y}%"><i>${icon}</i><span>${label} · ${winter?'敲响':'留下印记'}</span></button>`;}).join('')+`<div class="away-signpost melody-postbox" style="left:19%;top:22%"><span>${winter?'广场的乐谱':'一封夏日来信'}</span><p>${winter?'星星亮起，铃铛回响，月亮道晚安。':'先捡贝壳，经过浪花，再让海鸥捎信。'}</p><div class="away-sequence">${s.sequence.map(id=>scene.symbols.find(x=>x[0]===id)[1]).join(' ')||'去场景里找三个印记'}</div><div class="actions"><button id="awayClear">重新排列</button><button id="awayFinish" class="primary">${winter?'奏响雪夜钟声':'投进漂流信箱'}</button></div></div>`;}
 else main+=scene.symbols.map(([key,icon,label],i)=>futureDevice(2,s,(winter?'钟声 · ':'来信 · ')+label,icon,...loc.symbols[i])).join('');
 if(s.stage===3)main+=`<div class="away-signpost painted-ending" style="left:41%;top:51%"><span>✦ 本章通关 ✦</span><h3>${winter?'整条街都亮起来了。':'来信正沿着海风出发。'}</h3><p>你完成了三项任务。还可以找找场景里的小故事，留下两份旅行纪念。</p><button id="awayWinMap" class="primary">选择其他章节</button></div>`;return main+extras;
};
function openSceneExtra(id,key){const e=sceneExtras(id),winter=id==='winter';if(key==='friend'){const scene=AwayScenes.find(x=>x.id===id),s=awayProgress(id);modal(`<span class="eyebrow">${winter?'雪夜小邮差':'海鸥阿白'} · 跟你说句话</span><h2 id="dialogTitle">${s.completed?'这次旅途，你做到了。':'先看看眼前这一小步。'}</h2><p>${taskHint(scene,s)}</p><p>${s.stage===0?(winter?'缎带颜色就是礼物的地址，放错了也不会丢。':'三枚碎片落在沙滩和浅水边，找到后挂到风铃架。'):s.stage===1?(winter?'开关会把亮的变暗、暗的变亮，注意它们连接的是哪几盏灯。':'木牌上的方向，对应从左到右三面航标。'):s.stage===2?'线索在来信或乐谱上，按里面的先后顺序，到场景里点击三个符号。':'想再逛一会儿？旁边还有两段小故事等你发现。'}</p><div class="actions"><button id="sceneExtraClose" class="primary">我去试试</button></div>`);$('sceneExtraClose').onclick=close;return;}
 if(key==='bottle'){modal(`<span class="eyebrow">潮水送来的小机关</span><h2 id="dialogTitle">拧开漂流瓶的三圈软木塞</h2><div class="bottle-toy" style="--twist:${e.bottle*30}deg">🍾</div><p id="bottleMessage">${e.bottle>=3?'瓶里的信写着：每一次回来，海岸都会留一个位置给你。':'瓶塞有点紧，轻轻转动它。 '+e.bottle+'/3 圈'}</p><div class="actions"><button id="bottleTurn" ${e.bottle>=3?'disabled':''}>转一圈瓶塞 ↻</button><button id="bottleKeep" class="primary" ${e.bottle>=3?'':'disabled'}>收好漂流来信</button><button id="sceneExtraClose">先放回沙滩</button></div>`);$('bottleTurn').onclick=()=>{e.bottle=Math.min(3,e.bottle+1);save();openSceneExtra(id,key);};$('bottleKeep').onclick=()=>{sceneMemento(id,'漂流来信');close();openAwayScene(id,'漂流来信已放进风景手帐。');};}
 if(key==='tide'){modal(`<span class="eyebrow">潮汐池 · 一次小小观察</span><h2 id="dialogTitle">把潮水慢慢退下去</h2><div class="tide-toy"><div id="tideWater" style="height:${100-e.tide}%"></div><span>🐚　🪸　🐚</span></div><label class="discovery-focus">推动潮汐尺，露出池底的贝壳<input id="tideSlider" type="range" min="0" max="100" value="${e.tide}" aria-label="调整潮汐尺"></label><p id="tideMessage">${e.tide>=80?'池底的三枚贝壳都露出来了。':'潮水退到 '+e.tide+'%，再观察一会儿。'}</p><div class="actions"><button id="tideStep">让潮水再退一些</button><button id="tideKeep" class="primary" ${e.tide>=80?'':'disabled'}>画进潮汐手绘</button><button id="sceneExtraClose">回到海岸</button></div>`);const update=()=>{e.tide=Math.min(100,Math.max(0,+$('tideSlider').value));$('tideWater').style.height=(100-e.tide)+'%';$('tideMessage').textContent=e.tide>=80?'池底的三枚贝壳都露出来了。':'潮水退到 '+e.tide+'%，再观察一会儿。';$('tideKeep').disabled=e.tide<80;save();};$('tideSlider').oninput=update;$('tideStep').onclick=()=>{$('tideSlider').value=Math.min(100,e.tide+25);update();};$('tideKeep').onclick=()=>{if(e.tide<80)return;sceneMemento(id,'潮汐手绘');close();openAwayScene(id,'潮汐手绘已放进风景手帐。');};}
 if(key==='train'){modal(`<span class="eyebrow">雪夜列车 · 站台小机关</span><h2 id="dialogTitle">让小火车回到站台</h2><p>站台指示牌：第一岔向左、第二岔向右、第三岔向左。</p><div class="toy-train-track" id="toyTrainTrack"><span class="toy-train-engine">🚂</span> ${e.train.map((n,i)=>`<button data-track-turn="${i}">${n?'↗':'↖'}<small>道岔 ${i+1}</small></button>`).join('')} 🏠</div><p id="trainMessage">切换道岔，再试着发车。走错可以调回来。</p><div class="actions"><button id="trainGo" class="primary">发车，回到站台</button><button id="sceneExtraClose">先去送礼物</button></div>`);document.querySelectorAll('[data-track-turn]').forEach(el=>el.onclick=()=>{e.train[+el.dataset.trackTurn]=1-e.train[+el.dataset.trackTurn];save();openSceneExtra(id,key);});$('trainGo').onclick=()=>{if(e.train.join()!=='0,1,0'){$('trainMessage').textContent='岔路还没对齐，再看看站台指示牌。';return;}sceneMemento(id,'雪夜车票');$('toyTrainTrack').classList.add('train-arrived');$('trainMessage').textContent='小火车回站了！雪夜车票已放进风景手帐。';$('trainGo').disabled=true;};}
 if(key==='snowman'){modal(`<span class="eyebrow">雪人的衣帽架</span><h2 id="dialogTitle">帮它挑一身节日衣服</h2><div class="snowman-toy"><i style="background:${['#b55749','#648c62','#c8a454'][e.scarf]}"></i><span>${['🎩','🧢','👑'][e.hat]}</span><b>⛄</b><small>${['🧣 红围巾','🧣 绿围巾','🧣 金围巾'][e.scarf]}</small></div><p>没有标准答案，挑你喜欢的搭配，再留张合照。</p><div class="actions"><button id="snowHat">换一顶帽子</button><button id="snowScarf">换一条围巾</button><button id="snowPhoto" class="primary">留下雪人合照</button><button id="sceneExtraClose">回到街上</button></div>`);$('snowHat').onclick=()=>{e.hat=(e.hat+1)%3;save();openSceneExtra(id,key);};$('snowScarf').onclick=()=>{e.scarf=(e.scarf+1)%3;save();openSceneExtra(id,key);};$('snowPhoto').onclick=()=>{sceneMemento(id,'雪人合照');close();openAwayScene(id,'这身搭配和雪人合照，已经留在风景手帐里。');};}
 if($('sceneExtraClose'))$('sceneExtraClose').onclick=close;
}
function showSceneryJournal(id){const e=sceneExtras(id),all=id==='seaside'?['漂流来信','潮汐手绘']:['雪夜车票','雪人合照'];modal(`<span class="eyebrow">${AwayScenes.find(x=>x.id===id).name} · 风景手帐</span><h2 id="dialogTitle">留住这段路上的小发现</h2><div class="scenery-stamps">${all.map(n=>`<div class="${e.notes.includes(n)?'kept':''}"><b>${e.notes.includes(n)?'✦':'◇'}</b><strong>${n}</strong><small>${e.notes.includes(n)?'已经留下':'去场景里找找它的故事'}</small></div>`).join('')}</div><p>这些纪念不替代本章的三项任务。完成后可以随时回来看，换章也会保留。</p><div class="actions"><button id="closeSceneryJournal">合上手帐</button></div>`);$('closeSceneryJournal').onclick=close;}
const sceneryAway=openAwayScene;
openAwayScene=function(id,message=''){sceneryAway(id,message);if(!activeAwayScene)return;document.querySelectorAll('[data-future-device]').forEach(el=>el.onclick=()=>{const phase=+el.dataset.futureDevice,s=awayProgress(id),scene=AwayScenes.find(x=>x.id===id);awayFeedback(s.stage<phase?'暂未开始：先完成「'+scene.tasks[Math.max(0,phase-1)]+'」，这个机关就会启动。':'这个机关已经完成，变化会留在场景里。');});document.querySelectorAll('[data-scene-extra]').forEach(el=>el.onclick=()=>openSceneExtra(id,el.dataset.sceneExtra));const journal=document.createElement('button');journal.id='awayJournal';journal.className='away-journal-button';journal.textContent='风景手帐 '+sceneExtras(id).notes.length+'/2';journal.onclick=()=>showSceneryJournal(id);$('awayScene').appendChild(journal);};
const sceneryRestore=L.restore;
L.restore=function(raw){const s=sceneryRestore(raw);if(!s)return null;if(s.sceneExtras!==undefined){if(!s.sceneExtras||typeof s.sceneExtras!=='object'||Array.isArray(s.sceneExtras))return null;for(const[id,e]of Object.entries(s.sceneExtras)){const notes=id==='seaside'?['漂流来信','潮汐手绘']:['雪夜车票','雪人合照'];if(!['seaside','winter'].includes(id)||!e||!Number.isInteger(e.bottle)||e.bottle<0||e.bottle>3||!Number.isFinite(e.tide)||e.tide<0||e.tide>100||!Array.isArray(e.train)||e.train.length!==3||e.train.some(n=>![0,1].includes(n))||![e.hat,e.scarf].every(n=>Number.isInteger(n)&&n>=0&&n<3)||!Array.isArray(e.notes)||e.notes.length>2||new Set(e.notes).size!==e.notes.length||e.notes.some(n=>!notes.includes(n)))return null;}}return s;};
